import React from 'react';
import { motion } from 'framer-motion';
import { Link } from 'react-router-dom';
import AnimatedText from '../components/AnimatedText';
import blogData from '../data/blogData.json';
import './Blog.css';

const Blog = () => {
  return (
    <div className="page blog-listing-container container">
      <div className="section-header center-header">
        <AnimatedText text="Our Blog" el="h1" className="section-title" />
        <p className="section-subtitle">Stories, insights, and photography inspiration.</p>
      </div>

      <div className="blog-grid">
        {blogData.map((post, index) => {
          const date = new Date(post.published).toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'long',
            day: 'numeric'
          });

          return (
            <motion.div 
              key={post.id} 
              className="blog-card"
              initial={{ opacity: 0, y: 30 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true, margin: "-50px" }}
              transition={{ duration: 0.5, delay: (index % 3) * 0.1 }}
            >
              <Link to={`/blog/${post.slug}`} style={{ textDecoration: 'none', color: 'inherit', display: 'flex', flexDirection: 'column', height: '100%' }}>
                <div className="blog-card-image">
                  <img src={post.featuredImage} alt={post.title} />
                </div>
                <div className="blog-card-content">
                  <span className="blog-card-date">{date}</span>
                  <h3 className="blog-card-title">{post.title}</h3>
                  <p className="blog-card-excerpt">{post.excerpt}</p>
                  <span className="blog-card-link">Read More</span>
                </div>
              </Link>
            </motion.div>
          );
        })}
      </div>
    </div>
  );
};

export default Blog;
